import{_ as i,o as e,c as a,ag as o}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"Unciv 原版更新日志","description":"","frontmatter":{"title":"Unciv 原版更新日志"},"headers":[],"relativePath":"zh/Community/Upstream-changelog.md","filePath":"zh/Community/Upstream-changelog.md"}'),u={name:"zh/Community/Upstream-changelog.md"};function t(r,l,n,h,d,c){return e(),a("div",null,[...l[0]||(l[0]=[o('<h2 id="unciv-原版更新日志" tabindex="-1">Unciv 原版更新日志 <a class="header-anchor" href="#unciv-原版更新日志" aria-label="Permalink to &quot;Unciv 原版更新日志&quot;">​</a></h2><p>本文为 <a href="https://github.com/yairm210/Unciv/blob/master/changelog.md" target="_blank" rel="noreferrer">Unciv 官方更新日志</a> 的中文翻译，人工维护，覆盖近期版本（可能滞后于上游最新版）。 完整英文原文（自动同步，始终最新）请查看<a href="/Unciv/Community/Upstream-changelog.html">英文原版更新日志页</a>或仓库根目录 <code>changelog.md</code>。</p><hr><h2 id="_4-21-5" tabindex="-1">4.21.5 <a class="header-anchor" href="#_4-21-5" aria-label="Permalink to &quot;4.21.5&quot;">​</a></h2><ul><li>修复控制台删除文明不召回间谍 — By SomeTroglodyte</li><li>语音音量滑块实时生效 — By SomeTroglodyte</li><li>单独自动化的单位可以获得晋升 — By SomeTroglodyte</li><li>修复城市迷你统计面板数值取整 — By JPBergsma（新贡献者！）</li><li>修复军事单位赠礼通知位置 — By Angais</li><li>修复开放边境视野优先级 — By Angais</li><li>AI 优化建筑金币支出逻辑 — By EmperorPinguin</li><li>防止购买接近完工的建筑 — By EmperorPinguin</li></ul><h2 id="_4-21-4" tabindex="-1">4.21.4 <a class="header-anchor" href="#_4-21-4" aria-label="Permalink to &quot;4.21.4&quot;">​</a></h2><ul><li>地图卡顿与地图生成延迟的 CPU 性能优化</li><li>性能：科技选择界面 FPS 提升 — By shwwwa</li><li>修复城邦多疑概率计算 — By Angais</li><li>修复参战惩罚计算 — By Angais</li><li>修复两个 AI 评估 bug：WLTKD 奢侈品优先级反转、防御同盟盟友错用文明 — By WhoIsJohannes</li><li>修复两个 AI 太空竞赛 bug：太空资源储备失效、战争推进覆盖部分内容 — By WhoIsJohannes</li><li>城邦默认在出生地建立第一座城（可用 unique 关闭）— By Fanfblrik</li><li>新增出生地偏向 unique（通过 CityStateType uniques 实现 Maritime Coast）— By Fanfblrik</li><li>规则集校验器：警告潜在的无限循环（免费建筑 → 移除建筑）— By SomeTroglodyte</li><li>「从 URL 下载模组」允许填写指定 commit 链接 — By SomeTroglodyte</li></ul><h2 id="_4-21-3" tabindex="-1">4.21.3 <a class="header-anchor" href="#_4-21-3" aria-label="Permalink to &quot;4.21.3&quot;">​</a></h2><ul><li>修复杰内大清真寺在工业时代之前不生效</li><li>解放城邦时不再清空城邦关系 — By Fanfblrik</li><li>人口统计排名冻结为回合开始快照 — By Fanfblrik</li><li>修复：多人上传不再导致改良设施提前升级 — By cy-elec</li><li>AI 改进：并行移民、扩张解锁、研究协议、防御同盟护卫 — By WhoIsJohannes</li><li>CPU 性能优化 — By WhoIsJohannes</li><li>修复「单位损失时」触发器在新单位无法放置时触发 — By SomeTroglodyte</li><li>允许对 <code>UniqueType.HiddenFromCivilopedia</code> 使用有限条件 — By SomeTroglodyte</li><li>捕获从自定义位置加载的异常 — By SomeTroglodyte</li><li>修复地块信息「需要科技」行 — By SomeTroglodyte</li></ul><h2 id="_4-21-2" tabindex="-1">4.21.2 <a class="header-anchor" href="#_4-21-2" aria-label="Permalink to &quot;4.21.2&quot;">​</a></h2><ul><li>建筑禁用改为按城市/游戏生效，而非客户端全局 — By unciv-loof</li><li>用自由音效替换 -NC 音效 — By Wuzzy2</li><li>地块新增 <code>[Resource]</code>（感谢 Robloach）— By chenxing61</li><li>实现祖鲁伊姆皮（Impi）额外远程攻击 unique — By O-spin</li><li>模组检查器定位 <code>&lt;for every [resource]&gt;</code> 中循环的城市级资源 countable — By mvanhorn</li><li>模组管理器界面新增直接检查模组的按钮 — By SomeTroglodyte</li><li>政治总览「毛线球」改版 — By SomeTroglodyte</li><li>新城市总览列：多数宗教 — By SomeTroglodyte</li><li>允许像素单位美术选项与模组 extraImages 单位共存 — By SomeTroglodyte</li><li>无野蛮人游戏忽略 OneTimeRebel 与 OneTimeAmountRebels 触发器 — By SomeTroglodyte</li><li>修复 RekMod 摩艾石像可在带资源的水地块建造 — By SomeTroglodyte</li><li>美化城邦外交页面（当城邦有大量保护者时）— By SomeTroglodyte</li></ul><h2 id="_4-21-1" tabindex="-1">4.21.1 <a class="header-anchor" href="#_4-21-1" aria-label="Permalink to &quot;4.21.1&quot;">​</a></h2><ul><li>修复囤积资源交易未实际转移</li><li>性格的建造权重 unique — By SomeTroglodyte</li><li>修复平地地图无冰生成 — By SomeTroglodyte</li><li>修复地图通知地块选择 — By Angais</li><li>修复外部关闭时的选项清理 — By Angais</li><li>用兼容性更广的字符替换箭头 Unicode 字符 — By cy-elec</li><li>修复失去生命值的 uniques 缺少完整战斗上下文 — By SeventhM</li><li>为 mapunit 实现「other」参数 — By O-spin</li><li>修复强制辞职银行更新反转 — By L3odr0id</li><li>清理许可信息 — By Wuzzy2</li></ul><h2 id="_4-21-0" tabindex="-1">4.21.0 <a class="header-anchor" href="#_4-21-0" aria-label="Permalink to &quot;4.21.0&quot;">​</a></h2><ul><li>文明百科中显示领袖个性特征 — By SomeTroglodyte</li><li>重制胜利界面 — By cy-elec</li><li>Modding：允许为「数值或以上」类 uniques 传入参数 0 — By SeventhM</li><li>大量小修复 — By Angais（LLM 辅助）</li><li>修复 <code>allICivilopediaText</code> 中 <code>EventChoice</code> 条目重复的问题 — By xplon</li></ul><h2 id="_4-20-19" tabindex="-1">4.20.19 <a class="header-anchor" href="#_4-20-19" aria-label="Permalink to &quot;4.20.19&quot;">​</a></h2><ul><li>修复城市界面音频问题（待验证）</li><li>同一风格被多个文明共享时，文明图标与风格背景不再冲突</li><li>大量小修复 — By Angais（LLM 辅助）</li></ul><h2 id="_4-20-18" tabindex="-1">4.20.18 <a class="header-anchor" href="#_4-20-18" aria-label="Permalink to &quot;4.20.18&quot;">​</a></h2><ul><li>条件性工人 uniques 在禁用后不再引发崩溃</li><li>改良设施快捷键冲突时不再触发两次</li><li>文明专属图像优先于风格图像</li><li>修复 A* 寻路中「无移动力的单位将已占据地块视为可通行」的 Bug</li><li>南侧边缘的城市边界与城市按钮不再消失</li><li>CPU 性能优化</li><li>By unciv-loof： <ul><li>地图编辑器中新增镜像类型选项</li><li>调整地图类型排列顺序</li></ul></li></ul><h2 id="_4-20-17" tabindex="-1">4.20.17 <a class="header-anchor" href="#_4-20-17" aria-label="Permalink to &quot;4.20.17&quot;">​</a></h2><ul><li>CPU 性能优化</li><li>修复：在地图编辑器中移除蛮族营地时避免崩溃</li><li>调整 Boreal（北方针叶林）地图类型的湖泊与海岸线生成 — By unciv-loof</li><li>控制台：允许设置战略资源储量 — By SomeTroglodyte</li></ul><h2 id="_4-20-16" tabindex="-1">4.20.16 <a class="header-anchor" href="#_4-20-16" aria-label="Permalink to &quot;4.20.16&quot;">​</a></h2><ul><li>By unciv-loof： <ul><li>根据移动力上限限制 <code>AdditionalAttacks</code> 带来的战斗力加成</li><li>修复德国文明独特能力</li><li>修复边境军事威慑力计算</li></ul></li><li>使「蛮族营地」改良设施可被 Mod 自定义 — By SomeTroglodyte</li><li>By BobbyCobby： <ul><li>更清晰的 Mod 更新图标</li></ul></li><li>修复切换规则集时地图预览崩溃 — By Angais</li></ul><h2 id="_4-20-15" tabindex="-1">4.20.15 <a class="header-anchor" href="#_4-20-15" aria-label="Permalink to &quot;4.20.15&quot;">​</a></h2><ul><li>消耗库存资源的改良设施改为开始建造时即扣除资源（与建筑和单位一致）</li><li>减少大地图的内存占用</li><li>亲王（Prince）难度的 AI 不再享有单位造价减免（与玩家 1:1 平等）</li><li>要求 <code>CreatesOneImprovement</code> 的目标地块必须归属于建造城市 — By superdusto</li><li>资源总览标签页改进 — By SomeTroglodyte</li><li>Modding：修复 Personality uniques 的验证问题 — By mvanhorn</li></ul><h2 id="_4-20-14" tabindex="-1">4.20.14 <a class="header-anchor" href="#_4-20-14" aria-label="Permalink to &quot;4.20.14&quot;">​</a></h2><ul><li>修复「下一回合按钮黑屏」问题</li><li>右键菜单指示器不再常驻显示</li><li>缩放时城市按钮正确居中于地块</li><li>城市产出图标不再与人口图标重叠</li><li>By SomeTroglodyte： <ul><li>手势触发时长可在「选项 → 高级」中自定义</li><li>修复 unique 构建器中「选择音乐曲目」触发项</li><li>修复城邦始终显示「友好」个性的问题</li></ul></li><li>防止自动化清理 <code>CreatesOneImprovement</code> 标记残留 — By superdusto</li></ul><h2 id="_4-20-13" tabindex="-1">4.20.13 <a class="header-anchor" href="#_4-20-13" aria-label="Permalink to &quot;4.20.13&quot;">​</a></h2><ul><li>大幅降低大地图的内存占用</li><li>Modding：显示 JSON 文件错误的具体位置</li><li>By SomeTroglodyte： <ul><li>右键菜单视觉指示器</li><li>Modding：修复「空名称」问题</li><li>修复开疆扩土摧毁蛮族营地后遗留过期任务的问题</li><li>城市购买地块的右键菜单，支持一次购买多个地块</li></ul></li><li>避免镜头聚焦于隐藏奇观位置 — By xplon</li><li>验证晋升时尊重替代前置条件 — By superdusto</li></ul><h2 id="_4-20-12" tabindex="-1">4.20.12 <a class="header-anchor" href="#_4-20-12" aria-label="Permalink to &quot;4.20.12&quot;">​</a></h2><ul><li>By xplon： <ul><li>翻译间谍名称时隐藏图标</li><li>提示可翻译规则集名称冲突</li></ul></li><li>By SomeTroglodyte： <ul><li>改进右键菜单指示器大小</li><li>控制台新增 <code>civ add</code> 和 <code>civ remove</code> 命令</li></ul></li><li>高级游戏设置中新增缺失的换行 — By unciv-loof</li></ul><h2 id="_4-20-11" tabindex="-1">4.20.11 <a class="header-anchor" href="#_4-20-11" aria-label="Permalink to &quot;4.20.11&quot;">​</a></h2><ul><li>修复伟人建造伟人改良设施时出现重复按钮的问题</li><li>修复 Android 自定义文件目录</li><li>允许 Mod 常量验证器中值为 0 — By unciv-loof</li><li>By SomeTroglodyte： <ul><li>修复通知中统计符号的黑色描边</li><li>修复 <code>TriggerUponLosingUnit</code>（单位阵亡触发）</li><li>修复 Android 屏幕键盘显示/隐藏问题</li><li>轻微 CPU 性能优化</li></ul></li><li>为沼泽地块增加「植被」标签 — By EmperorPinguin</li></ul><h2 id="_4-20-10" tabindex="-1">4.20.10 <a class="header-anchor" href="#_4-20-10" aria-label="Permalink to &quot;4.20.10&quot;">​</a></h2><ul><li>By SomeTroglodyte： <ul><li>免费政策通知点击后直接打开政策界面</li><li>新增「选择音乐曲目」可触发 unique</li><li>优化剧本启动，减少意外情况</li></ul></li><li>Boreal（北方针叶林）地图类型 — By unciv-loof</li></ul><h2 id="_4-20-9" tabindex="-1">4.20.9 <a class="header-anchor" href="#_4-20-9" aria-label="Permalink to &quot;4.20.9&quot;">​</a></h2><ul><li>AI 在游戏后期不再停止建造城市</li><li>间谍管理界面新增国家与首都指示器</li><li>工人单位尽量分散作业 — By Ambeco</li><li>By SomeTroglodyte： <ul><li>正确显示改良设施维护费的修正值</li><li>修复注释嵌套 typed uniques 的翻译生成</li></ul></li><li>By unciv-loof： <ul><li>阻止 AI 谴责已灭亡的文明</li><li>多人游戏元数据预览中不再显示（Unknown）文明名</li></ul></li><li>修复「受过教育的精英」政策不赠送伟人的问题 — By AutumnPizazz</li></ul><h2 id="_4-20-8" tabindex="-1">4.20.8 <a class="header-anchor" href="#_4-20-8" aria-label="Permalink to &quot;4.20.8&quot;">​</a></h2><ul><li>程序化地图的无缝世界包裹生成 — By Romelium</li><li>By SomeTroglodyte： <ul><li>改善小屏幕下的「战报表」</li><li>CPU 性能优化</li></ul></li><li>RAM 性能优化 — By Ambeco</li></ul><h2 id="_4-20-7" tabindex="-1">4.20.7 <a class="header-anchor" href="#_4-20-7" aria-label="Permalink to &quot;4.20.7&quot;">​</a></h2><ul><li>大幅地图的渲染性能优化</li><li>修复军事存在检查的 Bug — by unciv-loof</li><li>新增 &quot;cannot build xx buildings&quot; unique — by chenxing61</li></ul><h2 id="_4-20-6" tabindex="-1">4.20.6 <a class="header-anchor" href="#_4-20-6" aria-label="Permalink to &quot;4.20.6&quot;">​</a></h2><p>By SeventhM:</p><ul><li><p>允许在全局/政策/时代 unique 中启用大使馆，不再仅限于科技</p></li><li><p>修复派遣大使馆的冗余条件要求</p></li><li><p>新增已工作地块/人口的计数条件</p></li><li><p>修复大先知花费异常计算的边界情况</p></li><li><p>改进语言处理，优化首次运行语言选择器的体验 — By SomeTroglodyte</p></li><li><p>CPU 性能优化 — By Ambeco</p></li></ul><h2 id="_4-20-5" tabindex="-1">4.20.5 <a class="header-anchor" href="#_4-20-5" aria-label="Permalink to &quot;4.20.5&quot;">​</a></h2><ul><li><strong>模组开发</strong>：正确处理规则集禁用 unique 时的过滤 unique</li><li><strong>模组开发</strong>：检测 AI 可能陷入死循环的事件链</li></ul><p>By SomeTroglodyte:</p><ul><li><p>改进文明百科中与大使馆相关的外交概念说明</p></li><li><p>修复地图编辑器崩溃</p></li><li><p>新增&quot;单位阵亡时触发&quot; unique — By PLynx01</p></li><li><p>处理所有屏幕方向的显示裁切，修复旋转问题 — By Gatien-L</p></li></ul><h2 id="_4-20-4" tabindex="-1">4.20.4 <a class="header-anchor" href="#_4-20-4" aria-label="Permalink to &quot;4.20.4&quot;">​</a></h2><ul><li><strong>模组开发</strong>：当 unique 在当前规则集中被禁用时，忽略与该规则集相关的错误</li></ul><p>By SomeTroglodyte:</p><ul><li>宗教/间谍系统被禁用时隐藏相关需求</li><li>修复在间谍界面将间谍移动到未知文明城市时的空指针异常</li></ul><p>By unciv-loof:</p><ul><li>补充城市抵抗状态的缺失表格行</li></ul><p>By Ambeco:</p><ul><li><p>Unciv 可直接接收游戏邀请或好友添加链接</p></li><li><p>防止更多类型的随机结果被 SL 利用</p></li><li><p>新增选项：禁止工人移除植被 — By Emandac</p></li></ul><h2 id="_4-20-3" tabindex="-1">4.20.3 <a class="header-anchor" href="#_4-20-3" aria-label="Permalink to &quot;4.20.3&quot;">​</a></h2><ul><li>从旧存档开始新游戏时，自定义地图将被保留</li><li>被摧毁城市中的间谍正确撤离</li><li>观察者可以再次查看建筑列表</li></ul><p>By unciv-loof:</p><ul><li><p>违背不再刺探承诺前弹出确认框</p></li><li><p>ConstructImprovementInstantly 现在会清除地块改良队列</p></li><li><p>修复城市中单位选择的 Bug — By ValeraShimchuck</p></li></ul><p>By Ambeco:</p><ul><li>AI：攻击前最小化移动</li><li>PathingMap 现在支持 BFS，将移动消耗纳入考虑</li></ul><h2 id="_4-20-2" tabindex="-1">4.20.2 <a class="header-anchor" href="#_4-20-2" aria-label="Permalink to &quot;4.20.2&quot;">​</a></h2><p>By unciv-loof:</p><ul><li><p>恢复显示设置中禁用单位模型渲染的选项</p></li><li><p>关闭新游戏界面警告后不再强制重置模组选择</p></li><li><p>点击勒索和征服城邦任务时，地图视角居中到目标首都</p></li><li><p>宣战弹窗中不再显示空消息</p></li><li><p>AI 可同时谴责多个文明</p></li><li><p>允许通过触发器获得的信仰使用可触发的 unique — by SeventhM</p></li><li><p>海洋浮冰应再次生成 — by Ambeco</p></li></ul><h2 id="_4-20-1" tabindex="-1">4.20.1 <a class="header-anchor" href="#_4-20-1" aria-label="Permalink to &quot;4.20.1&quot;">​</a></h2><ul><li>大幅降低内存消耗</li><li>地块进入文明领土时移除野蛮人营地</li><li>对第三方的和平/宣战声明不再被视为贸易&quot;赠礼&quot;</li><li>修复城市购买时的罕见崩溃</li><li>具有&quot;迁都时迁移至新首都&quot;属性的建筑在城市被占领时不再被摧毁</li><li>桌面可执行文件：最大 JVM 内存实际提升至 4GB</li><li>通知按顺序在 UI 中显示</li></ul><p>By unciv-loof:</p><ul><li>谴责弹窗支持可模组化的消息和音效</li><li>第 0 回合自动存档</li></ul><h2 id="_4-20-0" tabindex="-1">4.20.0 <a class="header-anchor" href="#_4-20-0" aria-label="Permalink to &quot;4.20.0&quot;">​</a></h2><p>By unciv-loof:</p><ul><li>修复大使馆贸易逻辑 Bug</li><li>其他文明回应要求后弹出通知</li></ul><p>By SeventhM:</p><ul><li><p>新增当前单位移动力条件判断</p></li><li><p>修复禁用的 unique 在意想不到的地方被忽略的问题</p></li><li><p>工人自动化性能的理论性改进 — By Ambeco</p></li><li><p>修复多人游戏预览描述中的翻译 — By evanofficial（新贡献者！）</p></li><li><p>新增&quot;签署和平条约时触发&quot; unique — By PLynx01</p></li></ul><h2 id="_4-19-19" tabindex="-1">4.19.19 <a class="header-anchor" href="#_4-19-19" aria-label="Permalink to &quot;4.19.19&quot;">​</a></h2><ul><li>删除包含地块集的模组后重置地块集设置</li><li>AI 忽略已灭亡文明的要求/宣友</li></ul><p>By Ambeco:</p><ul><li><p>AStar 寻路不再将河流视为多回合障碍</p></li><li><p>平面六角地图不再崩溃</p></li><li><p>Bug 修复：不要在已有平民单位的城市中尝试购买传教士 — By EmperorPinguin</p></li></ul><h2 id="_4-19-18" tabindex="-1">4.19.18 <a class="header-anchor" href="#_4-19-18" aria-label="Permalink to &quot;4.19.18&quot;">​</a></h2><ul><li>忽略免费晋升的晋升路径成本</li><li>允许在获得经验值之前获得免费晋升</li></ul><p>By Ambeco:</p><ul><li><p>模组可以有多个海洋和海岸地形</p></li><li><p>AStar 移动经过与 Classic 相同的格子</p></li><li><p>新增 showDemographics 选项 — By ICanSeeForever</p></li><li><p>强制解散单位考虑退款能力和晋升 — By unciv-loof</p></li><li><p>DenounceWillingness 人格特质 — by unciv-loof</p></li><li><p>AI：只有在能创立自己宗教时才因传教而生气 — By EmperorPinguin</p></li></ul><h2 id="_4-19-17" tabindex="-1">4.19.17 <a class="header-anchor" href="#_4-19-17" aria-label="Permalink to &quot;4.19.17&quot;">​</a></h2><ul><li>新游戏界面切换规则集不再允许零胜利类型</li><li>用户无法通过 &quot;-50&quot; 按钮提供负数金币</li></ul><p>By unciv-loof:</p><ul><li>通知显示谁跳过或退出了玩家</li><li>新获取的模组条目尊重当前过滤器</li><li>宣战 + 宣友 UI 改进</li></ul><p>By Ambeco:</p><ul><li>修复备用寻路 Bug</li><li>单位行动和单位触发器具有可模组化的优先级</li><li>消除了大多数硬编码地形</li></ul><h2 id="_4-19-16" tabindex="-1">4.19.16 <a class="header-anchor" href="#_4-19-16" aria-label="Permalink to &quot;4.19.16&quot;">​</a></h2><ul><li>默认最大内存从 1GB 提升至 4GB——2026 年了，让玩家尽情发挥吧</li><li>间谍城市视野限制功能 — By ICanSeeForever</li><li>淡水自然奇观不再显示为湖泊 — By Ambeco</li><li>根据游戏速度调整要求和&quot;我们爱国王日&quot;持续时间 — By unciv-loof</li></ul><h2 id="_4-19-15" tabindex="-1">4.19.15 <a class="header-anchor" href="#_4-19-15" aria-label="Permalink to &quot;4.19.15&quot;">​</a></h2><ul><li>更明确地警告大地图可能导致内存崩溃</li><li>规则集验证中捕获带有 occursOn 的基础地形</li><li>移除含有改良设施创建建筑但无城市地块的改良设施时不再崩溃</li><li>城市可以攻击已揭示的隐身单位</li></ul><p>By Ambeco:</p><ul><li><p>添加备用寻路算法</p></li><li><p>丛林不再生成在丘陵上</p></li><li><p>地图生成时忽略稀有要素放置普通地块</p></li><li><p>为可计数表达式添加 max()、min() 函数 — By AutumnPizazz</p></li></ul><h2 id="_4-19-14" tabindex="-1">4.19.14 <a class="header-anchor" href="#_4-19-14" aria-label="Permalink to &quot;4.19.14&quot;">​</a></h2><ul><li>在地图上为当前提供的资源添加星标图标</li><li>统一下 N 次晋升与单次晋升的经验值成本</li><li>AI 自动谴责 — By unciv-loof</li></ul><p>By AutumnPizazz:</p><ul><li><p>新增游戏选项隐藏胜利画面统计数据</p></li><li><p>将 &#39;Set [stockpile] to [amount]&#39; 改为 &#39;Set [stockpile] to [countable]&#39;</p></li><li><p>地图生成支持多种山脉、丘陵、冰层、雪地、湖泊和植被 — By Ambeco</p></li></ul><h2 id="_4-19-13" tabindex="-1">4.19.13 <a class="header-anchor" href="#_4-19-13" aria-label="Permalink to &quot;4.19.13&quot;">​</a></h2><ul><li>清除被复活文明的修正器和倒计时</li><li>傀儡城市正确移除&quot;由建筑标记为待改良&quot;的标记</li></ul><p>模组开发：</p><ul><li>特定金币购买费用 unique 始终覆盖默认费用</li><li>放置在单位上的全局 unique 可接受单位触发条件</li></ul><p>By unciv-loof:</p><ul><li>边境扩张逻辑优化： <ul><li>考虑工作范围边缘的邻近加成资源</li><li>不考虑未探索地块</li><li>略微优先选择有争议的地块</li></ul></li></ul><h2 id="_4-19-12" tabindex="-1">4.19.12 <a class="header-anchor" href="#_4-19-12" aria-label="Permalink to &quot;4.19.12&quot;">​</a></h2><ul><li>被覆盖政策分支中的政策不再&quot;残留&quot;影响 UI</li><li>在资源概览中添加已库存战略资源</li><li>新增 &quot;Set [stockpile] to [amount]&quot; 触发型 unique</li><li>未经用户允许不自动复制模组列表下载错误到剪贴板</li><li>加载缺少模组的游戏时先下载所有可用模组，再通知问题</li><li>查找文明等效单位时，若替代单位在规则集中不存在，不再崩溃</li></ul><h2 id="_4-19-11" tabindex="-1">4.19.11 <a class="header-anchor" href="#_4-19-11" aria-label="Permalink to &quot;4.19.11&quot;">​</a></h2><ul><li>&quot;单位可晋升&quot;通知显示正确的单位名称</li><li>修复第三方文明的宣友外交变化</li><li>对累积型外交修正器添加限制，特别是针对受保护城邦的负面修正器</li><li>城邦任务采用&quot;一致性随机&quot;</li><li>修复伟人不创建改良设施的问题</li><li>当单位无法接近目标时派遣不再导致单位图片消失</li><li>&quot;Must not be on [amount] largest landmasses&quot; 兼容资源 — By chenxing61</li></ul><h2 id="_4-19-10" tabindex="-1">4.19.10 <a class="header-anchor" href="#_4-19-10" aria-label="Permalink to &quot;4.19.10&quot;">​</a></h2><ul><li>新增 <code>[cityFilter] Cities of [civFilter] Civilizations</code> 可计数条件 — By RobLoach</li><li>人口食物消耗 unique — By PLynx01</li><li>修复胜利画面图表对观察者的可见性和布局 — By SomeTroglodyte</li><li>在线游戏可自定义游戏时长 — By AubertJocelyn（新贡献者！）</li></ul><hr><div class="tip custom-block"><p class="custom-block-title">更多版本</p><p>以上为已翻译的近期版本。完整历史版本（英文原文，自动同步）请查看<a href="/Unciv/Community/Upstream-changelog.html">英文原版更新日志页</a>或 <a href="https://github.com/yairm210/Unciv/blob/master/changelog.md" target="_blank" rel="noreferrer">Unciv 官方更新日志</a>。</p></div>',112)])])}const s=i(u,[["render",t]]);export{p as __pageData,s as default};
